    Case("t2a", *c2b_voice(3, 2, h=0x77, playing=1)),           # type 2, playing: return 0
    Case("t2b", *c2b_voice(4, 2, h=0x78, b=3, playing=0)),      # type 2, free: queue
    Case("t3a", *c2b_voice(0x46, 3, h=1, playing=1)),           # id 0x46, playing
