    p = d2b_pos_pokes({ents[i][1]: (i + 1, v) for i, (_, v) in enumerate(nodes)}) if nodes \
        else {0x001014EC: le32(D2B_PSET)}
    p[D2B_LIST] = le32(ents[0][0] if nodes else D2B_LIST) + le32(0x0BAD0004)
