def d2b_free_list(nodes, head=D2B_FREE):
    """A circular doubly linked list at `head` holding `nodes` in order."""
    ring = [head] + list(nodes)
    p = {}
    for i, n in enumerate(ring):
        p[n] = le32(ring[(i + 1) % len(ring)]) + le32(ring[i - 1])
    return p


