        p[0x000BEEF8 + ch[k] * 2] = le16(w[k] ^ 0x0F0F)
        if ch[k] >= 0x80:
            p[0x000BEEF8 + (ch[k] - 0x100) * 4] = le16(w[k] ^ 0x3333)
