    p.update(d1d_chunks(C2B_PAL_TABLE, t))
    p[C2B_PAL_TAIL] = le32(C2B_DIRTY) + le32(0x9C9D9E9F) + le32(0) + le32(0xA4A5A6A7)
    p.update(d1d_chunks(C2B_DIRTY, b"\xa5" * 0x60))
