    p[0x00104AB4] = le32(0xB4B4B4B4) + le32(0xB8B8B8B8 ^ k) + le32(0xBCBCBCBC)
    p[0x00104B1E] = bytes([0x1E, 0x1F ^ (k & 0xFF), 0x20])
    return p


