    d5g_mr("u1", D5G_T0, 0x00008000, flags=1),
    d5g_mr("u2", [D5G_MR_HDR(), (5, 6, D5G_CBK, 0)], 0x80008000),
    d5g_mr("u3", D5G_T1, 0x80000000, stride=0x14),
    d5g_mr("d0", D5G_T0, 0x40000000),
    d5g_mr("d1", D5G_T2, 0x00004000, stride=0x14),
