    d5g_mr("d3", D5G_T1, 0xC000C000),
    d5g_mr("d5", [D5G_MR_HDR(), (5, 6, D5G_CBK, 0), (2, 0, D5G_CBK, 0)], 0x00004000),
    d5g_mr("d4", D5G_T1, 0x40000000),
    d5g_mr("n0", D5G_T0, 0x01000000, cb_eax=5),
